scriptData.script:
const AP = args?.AP;
if (!AP) return;

console.log("[PathOfIron][APCalc] AP before", foundry.utils.deepClone(AP));

// Tentativa comum: aumentar AP por localização
// Ajuste os keys conforme seu AP object (use o log acima pra ver)
for (const loc of ["lArm", "rArm", "lLeg", "rLeg"]) {
  if (AP.locations?.[loc]?.value != null) AP.locations[loc].value += 2;
  else if (AP[loc]?.value != null) AP[loc].value += 2;
  else if (AP[loc] != null && typeof AP[loc] === "number") AP[loc] += 2;
}

console.log("[PathOfIron][APCalc] AP after", foundry.utils.deepClone(AP));

